import { useSelector } from 'react-redux';
import Navbar from './components/Navbar';
import Header from './components/Header';
import Footer from './components/Footer';
import StudentDashboard from './screens/StudentDashboard';
import LessonPlanScreen from './screens/LessonPlanScreen';
import QuizScreen from './screens/QuizScreen';
import ProgressTrackingBar from './screens/ProgressTrackingBar';
import GamifiedRewardsDisplay from './screens/GamifiedRewardsDisplay';

function App() {
  const currentScreen = useSelector((state) => state.navigation.currentScreen);

  const renderScreen = () => {
    switch (currentScreen) {
      case 'StudentDashboard':
        return <StudentDashboard />;
      case 'LessonPlanScreen':
        return <LessonPlanScreen />;
      case 'QuizScreen':
        return <QuizScreen />;
      case 'ProgressTrackingBar':
        return <ProgressTrackingBar />;
      case 'GamifiedRewardsDisplay':
        return <GamifiedRewardsDisplay />;
      default:
        return <StudentDashboard />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-50">
      <Header />
      <Navbar />
      <main className="flex-grow container mx-auto px-4 py-8">
        {renderScreen()}
      </main>
      <Footer />
    </div>
  );
}

