    "src/screens/LessonPlanScreen.jsx": "import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import Papa from 'papaparse';
import { startLesson } from '../store/studentSlice';
import AlertMessage from '../components/AlertMessage';
import { v4 as uuidv4 } from 'uuid';

// Mock CSV data for lesson plans
const mockLessonCsv = `id,title,description,duration,difficulty
${uuidv4()},Introduction to Algebra,Learn basic algebraic operations,30,Easy
${uuidv4()},Geometry Fundamentals,Explore shapes and angles,45,Medium
${uuidv4()},Probability Basics,Understand chances and outcomes,60,Hard`;

function LessonPlanScreen() {
  const dispatch = useDispatch();
  const studentName = useSelector((state) => state.student.studentProfile.name);
  const currentLessonId = useSelector((state) => state.student.currentLessonId);
  const [availableLessons, setAvailableLessons] = useState([]);
  const [message, setMessage] = useState(null);
  const [messageType, setMessageType] = useState('info');

  useEffect(() => {
    // Simulate fetching lesson plans from a CSV file using PapaParse
    Papa.parse(mockLessonCsv, {
      header: true,
      complete: (results) => {
        setAvailableLessons(results.data);
      },
      error: (error) => {
        console.error('Error parsing CSV:', error);
        setMessage('Failed to load lesson plans.');
        setMessageType('error');
      }
    });
  }, []);

  const handleStartLesson = (lessonId) => {
    dispatch(startLesson(lessonId));
    setMessage(`Lesson ${lessonId} started! Good luck, ${studentName}.`);
    setMessageType('success');
    setTimeout(() => setMessage(null), 3000); // Clear message after 3 seconds
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <h1 className="text-4xl font-extrabold text-dark mb-8 text-center md:text-left">
        Lesson Plans
      </h1>

      {message && <AlertMessage message={message} type={messageType} className="mb-6" />}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {availableLessons.length > 0 ? (
          availableLessons.map((lesson) => (
            <div key={lesson.id} className="bg-white rounded-xl shadow-lg p-6 transform hover:scale-105 transition-transform duration-300">
              <h2 className="text-2xl font-bold text-primary mb-2">{lesson.title}</h2>
              <p className="text-gray-700 mb-4">{lesson.description}</p>
              <div className="flex justify-between items-center text-sm text-gray-600 mb-4">
                <span>Duration: {lesson.duration} mins</span>
                <span className={`px-3 py-1 rounded-full ${lesson.difficulty === 'Easy' ? 'bg-green-100 text-green-800' : lesson.difficulty === 'Medium' ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'}`}>
                  {lesson.difficulty}
                </span>
              </div>
              {currentLessonId === lesson.id ? (
                <button
                  className="w-full bg-gray-400 text-white font-semibold py-3 px-6 rounded-lg cursor-not-allowed"
                  disabled
                >
                  In Progress
                </button>
              ) : (
                <button
                  onClick={() => handleStartLesson(lesson.id)}
                  className="w-full bg-primary hover:bg-primary-dark text-white font-semibold py-3 px-6 rounded-lg transition-colors duration-300"
                >
                  Start Lesson
                </button>
              )}
            </div>
          ))
        ) : (
          <p className="text-gray-600 text-lg col-span-full text-center">Loading lesson plans or no lessons available.</p>
        )}
      </div>
    </div>
  );
}

export default LessonPlanScreen;",
    "src/screens/QuizScreen.jsx": "import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { completeQuiz } from '../store/studentSlice';
import QuizItem from '../components/QuizItem';
import AlertMessage from '../components/AlertMessage';
import { v4 as uuidv4 } from 'uuid';

const mockQuizzes = [
  {
    id: uuidv4(),
    lessonId: 'intro-algebra-1',
    title: 'Algebra Basics Quiz',
    questions: [
      { id: 'q1', text: 'What is 2 + 2?', options: ['3', '4', '5'], answer: '4' },
      { id: 'q2', text: 'Solve for x: x + 5 = 10', options: ['3', '4', '5'], answer: '5' },
      { id: 'q3', text: 'Simplify: 3y + 2y', options: ['5y', '6y', '5y^2'], answer: '5y' }
    ]
  },
  {
    id: uuidv4(),
    lessonId: 'geometry-basics-1',
    title: 'Geometry Shapes Quiz',
    questions: [
      { id: 'q4', text: 'How many sides does a triangle have?', options: ['2', '3', '4'], answer: '3' },
      { id: 'q5', text: 'Which shape has 4 equal sides and 4 right angles?', options: ['Rectangle', 'Square', 'Circle'], answer: 'Square' }
    ]
  }
];

function QuizScreen() {
  const dispatch = useDispatch();
  const completedQuizzes = useSelector((state) => state.student.completedQuizzes);
  const [selectedAnswers, setSelectedAnswers] = useState({});
  const [quizResults, setQuizResults] = useState({});
  const [message, setMessage] = useState(null);
  const [messageType, setMessageType] = useState('info');

  const handleAnswerChange = (quizId, questionId, answer) => {
    setSelectedAnswers(prev => ({
      ...prev,
      [quizId]: {
        ...(prev[quizId] || {}),
        [questionId]: answer
      }
    }));
  };

  const handleSubmitQuiz = (quiz) => {
    let score = 0;
    const results = {};
    quiz.questions.forEach(q => {
      const isCorrect = selectedAnswers[quiz.id]?.[q.id] === q.answer;
      results[q.id] = isCorrect;
      if (isCorrect) {
        score++;
      }
    });
    setQuizResults(prev => ({ ...prev, [quiz.id]: { score, total: quiz.questions.length, results } }));
    dispatch(completeQuiz(quiz.id));
    setMessage(`Quiz '${quiz.title}' submitted! You scored ${score} out of ${quiz.questions.length}.`);
    setMessageType('success');
    setTimeout(() => setMessage(null), 5000);
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <h1 className="text-4xl font-extrabold text-dark mb-8 text-center md:text-left">
        Quizzes
      </h1>

      {message && <AlertMessage message={message} type={messageType} className="mb-6" />}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {mockQuizzes.map(quiz => (
          <div key={quiz.id} className="bg-white rounded-xl shadow-lg p-6">
            <QuizItem
              quiz={quiz}
              selectedAnswers={selectedAnswers[quiz.id] || {}}
              onAnswerChange={handleAnswerChange}
              onSubmit={handleSubmitQuiz}
              isCompleted={completedQuizzes.includes(quiz.id)}
              quizResults={quizResults[quiz.id]}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

export default QuizScreen;",
