  const mockBadges = [
    { id: 'b1', name: 'First Quiz Master', icon: '🏆', earned: completedQuizzes.length >= 1 },
    { id: 'b2', name: 'Algebra Pro', icon: '📐', earned: completedQuizzes.includes('algebra-basics-1') }, // Example quiz ID
    { id: 'b3', name: 'Consistent Learner', icon: '📚', earned: progressPercentage > 50 }
