      <h3 className="text-xl font-semibold text-dark mb-4">Milestones & Badges</h3>
      <div className="flex flex-wrap gap-4">
        {mockBadges.map((badge) => (
          <ProgressBadge key={badge.id} badge={badge} />
        ))}
      </div>

      <div className="mt-6">
        <h3 className="text-xl font-semibold text-dark mb-4">Teacher Insights (Simulated)</h3>
        {studentProgress.length > 0 ? (
          <ul className="list-disc list-inside text-gray-700">
