    "src/components/LessonItem.jsx": "import React from 'react';
import { useDispatch } from 'react-redux';
import { startLesson } from '../store/studentSlice';

function LessonItem({ lesson, isCurrent, isCompleted }) {
  const dispatch = useDispatch();

  const handleStart = () => {
    if (!isCurrent && !isCompleted) {
      dispatch(startLesson(lesson.id));
      alert(`You started lesson: ${lesson.title}`);
    }
  };

  const buttonClass = isCompleted
    ? 'bg-secondary text-white cursor-not-allowed'
    : isCurrent
    ? 'bg-gray-400 text-white cursor-not-allowed'
    : 'bg-primary hover:bg-indigo-600 text-white';

  return (
    <div className="bg-white rounded-xl shadow-lg p-6 flex flex-col justify-between transform hover:scale-105 transition-transform duration-300">
      <div>
        <h3 className="text-xl font-bold text-dark mb-2">{lesson.title}</h3>
        <p className="text-gray-700 mb-4 text-base">{lesson.description}</p>
      </div>
      <div className="flex items-center justify-between text-sm text-gray-600 mb-4">
        <span>Duration: {lesson.duration || 'N/A'} mins</span>
        <span className={`px-3 py-1 rounded-full ${lesson.difficulty === 'Easy' ? 'bg-green-100 text-green-800' : lesson.difficulty === 'Medium' ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'}`}>
          {lesson.difficulty || 'N/A'}
        </span>
      </div>
      <button
