import CodingPlayground from './screens/CodingPlayground';
import ProgressJournal from './screens/ProgressJournal';
import ParentTherapistPortal from './screens/ParentTherapistPortal';

function App() {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const toggleSidebar = () => {
    setIsSidebarOpen(!isSidebarOpen);
  };

  return (
    <div className="flex flex-col min-h-screen bg-gray-100">
      <Navbar />
      <div className="flex flex-1">
        {/* Hamburger menu for small screens / sidebar toggle */}
        <button
          onClick={toggleSidebar}
          className="fixed top-5 left-5 z-50 p-2 bg-blue-600 text-white rounded-md lg:hidden shadow-md"
        >
          {isSidebarOpen ? '✖' : '☰'}
        </button>

        <Sidebar isOpen={isSidebarOpen} toggleSidebar={toggleSidebar} />

        {/* Content Area */}
        <main className={`flex-1 transition-all duration-300 ${isSidebarOpen ? 'lg:ml-64' : 'ml-0'}`}>
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/game-hub" element={<GameHub />} />
            <Route path="/coding-playground" element={<CodingPlayground />} />
            <Route path="/progress-journal" element={<ProgressJournal />} />
            <Route path="/parent-therapist-portal" element={<ParentTherapistPortal />} />
          </Routes>
        </main>
      </div>
      <Footer />
    </div>
  );
}

export default App;

