import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import ProgressBar from '../components/ProgressBar';
import { addProgressEntry, addReward, addRecommendation, clearProgress } from '../store/slices/progressTrackingSlice';
import { v4 as uuidv4 } from 'uuid';

function ProgressJournal() {
  const dispatch = useDispatch();
  const { progressEntries, rewards, recommendations } = useSelector(state => state.progressTracking);

  // Mock progress data for demonstration
  const totalGamesPlayed = progressEntries.filter(entry => entry.type === 'game').length;
  const totalCodingChallenges = progressEntries.filter(entry => entry.type === 'coding').length;
  const overallProgress = Math.min(100, (totalGamesPlayed * 5 + totalCodingChallenges * 10)); // Arbitrary calculation

  const handleAddMockProgress = () => {
    dispatch(addProgressEntry({ activity: 'Completed "Pattern Puzzle" (Easy)', type: 'game', score: 85 }));
    dispatch(addReward({ name: 'Star Achiever Badge', description: 'Completed 5 games!' }));
    dispatch(addRecommendation({ type: 'game', suggestion: 'Try "Code Blocks" to enhance logical thinking.' }));
  };

  const handleClearAllProgress = () => {
    if (window.confirm("Are you sure you want to clear all progress, rewards, and recommendations? This cannot be undone.")) {
      dispatch(clearProgress());
    }
  };

  return (
    <div className="container mx-auto p-6 min-h-screen">
      <h1 className="text-4xl font-extrabold text-center text-gray-900 mb-8">
        Progress <span className="text-purple-600">Journal</span> 📈
      </h1>

      <div className="bg-white rounded-lg shadow-lg p-6 mb-8 border-t-4 border-purple-500">
        <h2 className="text-2xl font-bold text-gray-800 mb-4">Overall Progress</h2>
        <ProgressBar progress={overallProgress} label="Overall Learning" />
        <div className="mt-4 flex justify-center space-x-4">
          <button
            onClick={handleAddMockProgress}
            className="bg-blue-500 hover:bg-blue-600 text-white py-2 px-4 rounded-md transition duration-300"
          >
            Add Mock Progress
          </button>
          <button
            onClick={handleClearAllProgress}
            className="bg-red-500 hover:bg-red-600 text-white py-2 px-4 rounded-md transition duration-300"
          >
            Clear All Progress
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="bg-white rounded-lg shadow-lg p-6 border-t-4 border-green-500">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Learning Activities</h2>
          {progressEntries.length > 0 ? (
            <ul className="space-y-3">
              {progressEntries.map(entry => (
                <li key={entry.id} className="bg-green-50 p-3 rounded-md border border-green-200">
                  <p className="text-gray-800 text-lg font-medium">{entry.activity}</p>
                  <p className="text-gray-600 text-sm">Date: {new Date(entry.date).toLocaleDateString()} - Score: {entry.score || 'N/A'}</p>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-gray-600 italic">No learning activities recorded yet.</p>
          )}
        </div>

        <div className="space-y-8">
          <div className="bg-white rounded-lg shadow-lg p-6 border-t-4 border-yellow-500">
            <h2 className="text-2xl font-bold text-gray-800 mb-4">Your Rewards</h2>
            {rewards.length > 0 ? (
              <ul className="space-y-3">
                {rewards.map(reward => (
                  <li key={reward.id} className="bg-yellow-50 p-3 rounded-md border border-yellow-200">
                    <p className="text-gray-800 text-lg font-medium">🏆 {reward.name}</p>
                    <p className="text-gray-600 text-sm">{reward.description}</p>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-gray-600 italic">No rewards earned yet. Keep learning!</p>
            )}
          </div>

          <div className="bg-white rounded-lg shadow-lg p-6 border-t-4 border-blue-500">
            <h2 className="text-2xl font-bold text-gray-800 mb-4">Personalized Recommendations</h2>
            {recommendations.length > 0 ? (
              <ul className="space-y-3">
                {recommendations.map(rec => (
                  <li key={rec.id} className="bg-blue-50 p-3 rounded-md border border-blue-200">
                    <p className="text-gray-800 text-lg font-medium">💡 {rec.suggestion}</p>
                    <p className="text-gray-600 text-sm">Type: {rec.type}</p>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-gray-600 italic">No recommendations yet. Engage more to get personalized tips!</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default ProgressJournal;

