              <ul className="space-y-2 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                {progressTracking.recommendations.slice(-5).reverse().map(rec => (
                  <li key={rec.id} className="bg-blue-50 p-2 rounded-md border border-blue-200 text-sm">
                    {new Date(rec.date).toLocaleDateString()}: {rec.suggestion}
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-gray-600 italic">No recommendations provided yet.</p>
            )}
          </div>
        </div>
      </div>

