import { createSlice } from '@reduxjs/toolkit';
import { v4 as uuidv4 } from 'uuid';

const initialState = {
  id: uuidv4(),
  name: 'Learner User',
  age: 12,
  neurodiverseType: 'Autism Spectrum Disorder',
  avatar: 'https://i.pravatar.cc/150?img=3',
  preferences: {
    theme: 'light',
    fontSize: 'medium',
    visualAids: true,
  },
};

const learnerProfileSlice = createSlice({
  name: 'learnerProfile',
  initialState,
  reducers: {
    setProfileName: (state, action) => {
      state.name = action.payload;
    },
    setProfileAge: (state, action) => {
      state.age = action.payload;
    },
    setNeurodiverseType: (state, action) => {
      state.neurodiverseType = action.payload;
    },
    setAvatar: (state, action) => {
      state.avatar = action.payload;
    },
    setPreferences: (state, action) => {
      state.preferences = { ...state.preferences, ...action.payload };
    },
    resetProfile: (state) => {
      state.id = uuidv4();
      state.name = initialState.name;
      state.age = initialState.age;
      state.neurodiverseType = initialState.neurodiverseType;
      state.avatar = initialState.avatar;
      state.preferences = initialState.preferences;
    },
  },
});

export const {
  setProfileName,
  setProfileAge,
  setNeurodiverseType,
  setAvatar,
  setPreferences,
  resetProfile,
} = learnerProfileSlice.actions;

export default learnerProfileSlice.reducer;

