import { createSlice } from '@reduxjs/toolkit';
import { v4 as uuidv4 } from 'uuid';

const initialState = {
  progressEntries: [],
  rewards: [],
  recommendations: [],
};

const progressTrackingSlice = createSlice({
  name: 'progressTracking',
  initialState,
  reducers: {
    addProgressEntry: (state, action) => {
      state.progressEntries.push({ id: uuidv4(), date: new Date().toISOString(), ...action.payload });
    },
    addReward: (state, action) => {
      state.rewards.push({ id: uuidv4(), date: new Date().toISOString(), ...action.payload });
    },
    addRecommendation: (state, action) => {
      state.recommendations.push({ id: uuidv4(), date: new Date().toISOString(), ...action.payload });
    },
    clearProgress: (state) => {
      state.progressEntries = [];
      state.rewards = [];
      state.recommendations = [];
    },
  },
});

export const {
  addProgressEntry,
  addReward,
  addRecommendation,
  clearProgress,
} = progressTrackingSlice.actions;

export default progressTrackingSlice.reducer;

