import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import ProfileCard from '../components/ProfileCard';
import ProgressBar from '../components/ProgressBar';
import SettingsToggle from '../components/SettingsToggle';
import { setProfileName, setProfileAge, setNeurodiverseType } from '../store/slices/learnerProfileSlice';
import { addProgressEntry, addReward, addRecommendation } from '../store/slices/progressTrackingSlice';
import { v4 as uuidv4 } from 'uuid';

function ParentTherapistPortal() {
  const dispatch = useDispatch();
  const learnerProfile = useSelector(state => state.learnerProfile);
  const progressTracking = useSelector(state => state.progressTracking);

  const [goal, setGoal] = useState('');
  const [recommendationText, setRecommendationText] = useState('');

  const handleUpdateProfile = (field, value) => {
    if (field === 'name') dispatch(setProfileName(value));
    if (field === 'age') dispatch(setProfileAge(Number(value)));
    if (field === 'neurodiverseType') dispatch(setNeurodiverseType(value));
  };

  const handleSetGoal = () => {
    if (goal.trim()) {
      dispatch(addProgressEntry({ activity: `Goal Set: ${goal}`, type: 'goal', score: 0 }));
      setGoal('');
      alert('Goal added for learner!');
    }
  };

  const handleAddRecommendation = () => {
    if (recommendationText.trim()) {
      dispatch(addRecommendation({ type: 'manual', suggestion: recommendationText }));
      setRecommendationText('');
      alert('Recommendation added for learner!');
    }
  };

  // Mock progress calculation
  const overallLearningProgress = Math.min(100, (progressTracking.progressEntries.length * 7 + progressTracking.rewards.length * 10));

  return (
    <div className="container mx-auto p-6 min-h-screen">
      <h1 className="text-4xl font-extrabold text-center text-gray-900 mb-8">
        Parent/Therapist <span className="text-orange-600">Portal</span> 👨‍👩‍👧‍👦
      </h1>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-8">
        <div className="lg:col-span-1">
          <ProfileCard />
        </div>

        <div className="lg:col-span-2 bg-white rounded-lg shadow-lg p-6 border-t-4 border-orange-500">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Learner's Progress Overview</h2>
          <ProgressBar progress={overallLearningProgress} label="Overall Progress" />

          <div className="mt-6">
            <h3 className="text-xl font-semibold text-gray-800 mb-3">Recent Activities ({progressTracking.progressEntries.length})</h3>
            {progressTracking.progressEntries.length > 0 ? (
              <ul className="space-y-2 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                {progressTracking.progressEntries.slice(-5).reverse().map(entry => (
                  <li key={entry.id} className="bg-gray-50 p-2 rounded-md border border-gray-200 text-sm">
                    {new Date(entry.date).toLocaleDateString()}: {entry.activity} ({entry.type})
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-gray-600 italic">No activities recorded yet.</p>
            )}
          </div>

          <div className="mt-6">
            <h3 className="text-xl font-semibold text-gray-800 mb-3">Recommendations for Learner ({progressTracking.recommendations.length})</h3>
            {progressTracking.recommendations.length > 0 ? (
              <ul className="space-y-2 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                {progressTracking.recommendations.slice(-5).reverse().map(rec => (
                  <li key={rec.id} className="bg-blue-50 p-2 rounded-md border border-blue-200 text-sm">
                    {new Date(rec.date).toLocaleDateString()}: {rec.suggestion}
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-gray-600 italic">No recommendations provided yet.</p>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="bg-white rounded-lg shadow-lg p-6 border-t-4 border-blue-500">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Manage Learner Profile</h2>
          <div className="mb-4">
            <label htmlFor="learnerName" className="block text-gray-700 text-sm font-bold mb-2">Name:</label>
            <input
              type="text"
              id="learnerName"
              value={learnerProfile.name}
              onChange={(e) => handleUpdateProfile('name', e.target.value)}
              className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            />
          </div>
          <div className="mb-4">
            <label htmlFor="learnerAge" className="block text-gray-700 text-sm font-bold mb-2">Age:</label>
            <input
              type="number"
              id="learnerAge"
              value={learnerProfile.age}
              onChange={(e) => handleUpdateProfile('age', e.target.value)}
              className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            />
          </div>
          <div className="mb-4">
            <label htmlFor="neuroType" className="block text-gray-700 text-sm font-bold mb-2">Neurodiverse Type:</label>
            <input
              type="text"
              id="neuroType"
              value={learnerProfile.neurodiverseType}
              onChange={(e) => handleUpdateProfile('neurodiverseType', e.target.value)}
              className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
            />
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-white rounded-lg shadow-lg p-6 border-t-4 border-green-500">
            <h2 className="text-2xl font-bold text-gray-800 mb-4">Set Learning Goals</h2>
            <textarea
              className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-4 resize-y"
              rows="3"
              placeholder="e.g., 'Complete 3 coding challenges this week'"
              value={goal}
              onChange={(e) => setGoal(e.target.value)}
            ></textarea>
            <button
              onClick={handleSetGoal}
              className="w-full bg-green-600 text-white py-2 px-4 rounded-md hover:bg-green-700 transition duration-300"
            >
              Add Goal
            </button>
          </div>

          <div className="bg-white rounded-lg shadow-lg p-6 border-t-4 border-purple-500">
            <h2 className="text-2xl font-bold text-gray-800 mb-4">Add Personalized Recommendation</h2>
            <textarea
              className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-4 resize-y"
              rows="3"
              placeholder="e.g., 'Focus on improving pattern recognition skills with visual games.'"
              value={recommendationText}
              onChange={(e) => setRecommendationText(e.target.value)}
            ></textarea>
            <button
              onClick={handleAddRecommendation}
              className="w-full bg-purple-600 text-white py-2 px-4 rounded-md hover:bg-purple-700 transition duration-300"
            >
              Add Recommendation
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default ParentTherapistPortal;

