import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  selectedCategory: '10-15',
  difficultyLevel: 'easy',
  availableGames: [
    { id: 'g1', name: 'Pattern Puzzle', category: '10-15', difficulty: ['easy', 'medium', 'hard'], description: 'Match visual patterns to improve cognitive skills.' },
    { id: 'g2', name: 'Code Blocks', category: '10-15', difficulty: ['easy', 'medium'], description: 'Drag and drop blocks to learn basic coding logic.' },
    { id: 'g3', name: 'Story Weaver', category: '16-20', difficulty: ['medium', 'hard'], description: 'Create interactive stories with guided prompts.' },
    { id: 'g4', name: 'Logic Gates', category: '16-20', difficulty: ['medium', 'hard'], description: 'Build circuits using logic gates to solve challenges.' },
    { id: 'g5', name: 'Career Quest', category: '21-30', difficulty: ['hard'], description: 'Simulate real-world career scenarios and decision-making.' },
    { id: 'g6', name: 'Financial Literacy', category: '21-30', difficulty: ['medium', 'hard'], description: 'Learn about budgeting and financial planning.' },
  ],
};

const gameSelectionSlice = createSlice({
  name: 'gameSelection',
  initialState,
  reducers: {
    setSelectedCategory: (state, action) => {
      state.selectedCategory = action.payload;
    },
    setDifficultyLevel: (state, action) => {
      state.difficultyLevel = action.payload;
    },
    addGame: (state, action) => {
      state.availableGames.push(action.payload);
    },
    removeGame: (state, action) => {
      state.availableGames = state.availableGames.filter(game => game.id !== action.payload);
    },
  },
});

export const {
  setSelectedCategory,
  setDifficultyLevel,
  addGame,
  removeGame,
} = gameSelectionSlice.actions;

export default gameSelectionSlice.reducer;

