import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { setSelectedCategory, setDifficultyLevel } from '../store/slices/gameSelectionSlice';

function GameHub() {
  const dispatch = useDispatch();
  const { selectedCategory, difficultyLevel, availableGames } = useSelector(state => state.gameSelection);

  const categories = ['10-15', '16-20', '21-30'];
  const difficulties = ['easy', 'medium', 'hard'];

  const filteredGames = availableGames.filter(game =>
    game.category === selectedCategory && game.difficulty.includes(difficultyLevel)
  );

  return (
    <div className="container mx-auto p-6 min-h-screen">
      <h1 className="text-4xl font-extrabold text-center text-gray-900 mb-8">
        Game <span className="text-indigo-600">Hub</span> 🎮
      </h1>

      <div className="bg-white rounded-lg shadow-md p-6 mb-8 flex flex-wrap justify-center gap-4">
        <div className="flex flex-col items-center">
          <label htmlFor="category-select" className="text-lg font-semibold text-gray-700 mb-2">
            Age Group:
          </label>
          <select
            id="category-select"
            value={selectedCategory}
            onChange={(e) => dispatch(setSelectedCategory(e.target.value))}
            className="p-3 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 text-base"
          >
            {categories.map(cat => (
              <option key={cat} value={cat}>{cat}</option>
            ))}
          </select>
        </div>

        <div className="flex flex-col items-center">
          <label htmlFor="difficulty-select" className="text-lg font-semibold text-gray-700 mb-2">
            Difficulty:
          </label>
          <select
            id="difficulty-select"
            value={difficultyLevel}
            onChange={(e) => dispatch(setDifficultyLevel(e.target.value))}
            className="p-3 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 text-base capitalize"
          >
            {difficulties.map(diff => (
              <option key={diff} value={diff}>{diff}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredGames.length > 0 ? (
          filteredGames.map(game => (
            <div key={game.id} className="bg-white rounded-lg shadow-lg p-6 hover:shadow-xl transition-shadow duration-300 border-t-4 border-indigo-500">
              <h3 className="text-2xl font-bold text-gray-800 mb-2">{game.name}</h3>
              <p className="text-indigo-600 text-sm mb-3">Age Group: {game.category} | Difficulty: <span className="capitalize">{game.difficulty.join(', ')}</span></p>
              <p className="text-gray-700 mb-4">{game.description}</p>
              <button className="w-full bg-indigo-600 text-white py-2 px-4 rounded-md hover:bg-indigo-700 transition duration-300 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2">
                Play Now
              </button>
            </div>
          ))
        ) : (
          <p className="col-span-full text-center text-gray-600 text-xl">No games found for the selected criteria.</p>
        )}
      </div>
    </div>
  );
}

export default GameHub;

