import React, { useState } => 'React';

function CodingPlayground() {
  const [code, setCode] = useState('// Start coding here!\nfunction greet(name) {\n  console.log("Hello, " + name + "!");\n}\ngreet("Learner");');
  const [output, setOutput] = useState('');

  const runCode = () => {
    try {
      // Simple and unsafe way to run code, for demo purposes.
      // In a real app, this would involve a secure sandbox or backend execution.
      let consoleOutput = '';
      const originalConsoleLog = console.log;
      console.log = (...args) => {
        consoleOutput += args.map(arg => typeof arg === 'object' ? JSON.stringify(arg) : String(arg)).join(' ') + '\n';
      };

      eval(code); // Using eval for demonstration. Do NOT use in production for user-supplied code.

      console.log = originalConsoleLog; // Restore original console.log
      setOutput(consoleOutput || 'Code executed successfully (no console output).');
    } catch (error) {
      setOutput(`Error: ${error.message}`);
    }
  };

  const creativeProjects = [
    { id: 'p1', name: 'Interactive Story', description: 'Create a simple choose-your-own-adventure game.' },
    { id: 'p2', name: 'Shape Drawing', description: 'Write code to draw basic geometric shapes on a canvas.' },
  ];

  const dailyChallenges = [
    { id: 'c1', name: 'FizzBuzz', description: 'Print numbers 1 to 100. Multiples of 3 print "Fizz", multiples of 5 print "Buzz", both "FizzBuzz".' },
    { id: 'c2', name: 'Palindrome Checker', description: 'Write a function to check if a word is a palindrome.' },
  ];

  return (
    <div className="container mx-auto p-6 min-h-screen">
      <h1 className="text-4xl font-extrabold text-center text-gray-900 mb-8">
        Coding <span className="text-green-600">Playground</span> 💻
      </h1>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
        <div className="bg-white rounded-lg shadow-lg p-6 border-t-4 border-green-500">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Code Editor</h2>
          <textarea
            className="w-full h-80 p-4 border border-gray-300 rounded-md bg-gray-900 text-green-300 font-mono text-sm resize-y focus:outline-none focus:ring-2 focus:ring-green-500"
            value={code}
            onChange={(e) => setCode(e.target.value)}
            spellCheck="false"
          ></textarea>
          <button
            onClick={runCode}
            className="mt-4 w-full bg-green-600 text-white py-3 px-4 rounded-md hover:bg-green-700 transition duration-300 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 text-lg font-semibold"
          >
            Run Code
          </button>
        </div>

        <div className="bg-white rounded-lg shadow-lg p-6 border-t-4 border-blue-500">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Output</h2>
          <pre className="w-full h-96 p-4 border border-gray-300 rounded-md bg-gray-100 text-gray-800 font-mono text-sm overflow-auto whitespace-pre-wrap">
            {output || 'Your code output will appear here.'}
          </pre>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-8">
        <div className="bg-white rounded-lg shadow-lg p-6 border-t-4 border-purple-500">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Creative Projects</h2>
          {creativeProjects.map(project => (
            <div key={project.id} className="mb-4 p-4 border border-gray-200 rounded-md bg-purple-50">
              <h3 className="text-xl font-semibold text-gray-800">{project.name}</h3>
              <p className="text-gray-700 text-sm mt-1">{project.description}</p>
              <button className="mt-2 text-purple-600 hover:underline text-sm">Start Project</button>
            </div>
          ))}
        </div>

        <div className="bg-white rounded-lg shadow-lg p-6 border-t-4 border-orange-500">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Daily Challenges</h2>
          {dailyChallenges.map(challenge => (
