import React from 'react';
import { Link, NavLink } from 'react-router-dom';
import { useSelector } from 'react-redux';

function Navbar() {
  const { name, avatar } = useSelector(state => state.learnerProfile);

  const navItems = [
    { name: 'Home', path: '/' },
