import React from 'react';

function ProgressBar({ progress, label }) {
  const percentage = Math.max(0, Math.min(100, progress)); // Ensure progress is between 0 and 100

  return (
    <div className="w-full bg-gray-200 rounded-full h-4 relative overflow-hidden shadow-inner">
      <div
        className="bg-green-500 h-full rounded-full transition-all duration-500 ease-out"
        style={{ width: `${percentage}%` }}
      ></div>
      <div className="absolute inset-0 flex items-center justify-center">
        <span className="text-white text-xs font-semibold drop-shadow-sm">{label} {percentage}%</span>
      </div>
    </div>
  );
}

export default ProgressBar;

