import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { setPreferences } from '../store/slices/learnerProfileSlice';

function SettingsToggle({ settingKey, label, options, type = 'select' }) {
  const dispatch = useDispatch();
  const currentValue = useSelector(state => state.learnerProfile.preferences[settingKey]);

  const handleChange = (e) => {
    let value = e.target.value;
    if (type === 'checkbox') {
      value = e.target.checked;
    }
    dispatch(setPreferences({ [settingKey]: value }));
  };

  return (
    <div className="flex items-center justify-between p-4 bg-white rounded-lg shadow-sm mb-4 border-l-4 border-purple-400">
      <label htmlFor={settingKey} className="text-lg font-medium text-gray-700">
        {label}:
      </label>
      {type === 'select' && (
        <select
          id={settingKey}
          value={currentValue}
          onChange={handleChange}
          className="mt-1 block w-1/2 p-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-purple-500 focus:border-purple-500 sm:text-sm"
        >
          {options.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      )}
      {type === 'checkbox' && (
        <input
          type="checkbox"
          id={settingKey}
          checked={currentValue}
          onChange={handleChange}
          className="h-6 w-6 text-purple-600 focus:ring-purple-500 border-gray-300 rounded"
        />
      )}
    </div>
  );
}

export default SettingsToggle;
